export function createAlert(root) {
  const alerts = [...root.querySelectorAll('[data-alert]')];
  const controls = alerts.map((alert) => {
    const closeButton = alert.querySelector(':scope > [data-alert-close]');
    if (!(closeButton instanceof HTMLButtonElement)) {
      throw new Error('Alert dismiss controls are incomplete.');
    }

    const close = () => {
      if (alert.hidden) return;
      alert.hidden = true;
      root.dispatchEvent(new CustomEvent('alert:close', { detail: { alert } }));
    };

    closeButton.addEventListener('click', close);
    return { alert, close, closeButton };
  });

  if (!alerts.length) {
    throw new Error('Alert markup is incomplete.');
  }

  return {
    close(index = 0) {
      controls[index]?.close();
    },
    destroy() {
      controls.forEach(({ close, closeButton }) => closeButton.removeEventListener('click', close));
    }
  };
}

document.querySelectorAll('[data-component="alert"]').forEach(createAlert);

