export function createActionAlert(root) {
  const alert = root.querySelector('[data-alert]');
  const closeButton = alert?.querySelector('[data-alert-close]');
  const actionButton = alert?.querySelector('[data-alert-action]');

  if (!(alert instanceof HTMLElement)
      || !(closeButton instanceof HTMLButtonElement)
      || !(actionButton instanceof HTMLButtonElement)) {
    throw new Error('Action alert markup is incomplete.');
  }

  const close = () => {
    if (alert.hidden) return;
    alert.hidden = true;
    root.dispatchEvent(new CustomEvent('alert:close', { detail: { alert } }));
  };
  const handleAction = () => {
    root.dispatchEvent(new CustomEvent('alert:action', { detail: { alert } }));
  };

  closeButton.addEventListener('click', close);
  actionButton.addEventListener('click', handleAction);

  return {
    close,
    destroy() {
      closeButton.removeEventListener('click', close);
      actionButton.removeEventListener('click', handleAction);
    }
  };
}

document.querySelectorAll('[data-component="action-alert"]').forEach(createActionAlert);

