export function createFormErrorAlert(root) {
  const alert = root.querySelector('[data-alert]');
  const closeButton = alert?.querySelector('[data-alert-close]');
  const errorLink = alert?.querySelector('[data-alert-link]');
  if (!(alert instanceof HTMLElement)
      || !(closeButton instanceof HTMLButtonElement)
      || !(errorLink instanceof HTMLAnchorElement)) {
    throw new Error('Form error alert markup is incomplete.');
  }

  const close = () => {
    if (alert.hidden) return;
    alert.hidden = true;
    root.dispatchEvent(new CustomEvent('alert:close', { detail: { alert } }));
  };
  const handleLinkClick = (event) => {
    event.preventDefault();
  };

  closeButton.addEventListener('click', close);
  errorLink.addEventListener('click', handleLinkClick);
  return {
    close,
    destroy() {
      closeButton.removeEventListener('click', close);
      errorLink.removeEventListener('click', handleLinkClick);
    }
  };
}

document.querySelectorAll('[data-component="form-error-alert"]').forEach(createFormErrorAlert);

