export function createProgressBar(root) {
  const progress = root.querySelector('[role="progressbar"]');
  const bar = root.querySelector('[data-progress-bar]');
  const valueLabel = root.querySelector('[data-progress-value]');
  const buttons = [...root.querySelectorAll('[data-progress-set]')];
  if (!(progress instanceof HTMLElement) || !(bar instanceof HTMLElement) || !(valueLabel instanceof HTMLElement) || !buttons.length) throw new Error('Progress bar markup is incomplete.');

  const setValue = (nextValue) => {
    const value = Math.max(0, Math.min(100, Number(nextValue)));
    progress.setAttribute('aria-valuenow', String(value));
    bar.style.setProperty('--progress-value', `${value}%`);
    valueLabel.textContent = `${value}%`;
    root.dispatchEvent(new CustomEvent('progress:change', { detail: { value } }));
  };
  const handleClick = (event) => setValue(event.currentTarget.dataset.progressSet);
  buttons.forEach((button) => button.addEventListener('click', handleClick));
  return { setValue, destroy() { buttons.forEach((button) => button.removeEventListener('click', handleClick)); } };
}
document.querySelectorAll('[data-component="progress-bar"]').forEach(createProgressBar);

